b:if.script:
{
  "@context":"https://schema.org",

  "@type":"AboutPage",

  "@type":"ContactPage",

    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is CodeHemu?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "CodeHemu is a developer resource site focused on programming related topics. We publish tutorials, code snippets, CSS-art, small JS tools and step-by-step guides. CodeHemu helps you create animations and interactive effects."
        }
      },
      {
        "@type": "Question",
        "name": "Who is CodeHemu for?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "CodeHemu is designed for anyone interested in web design and development. It is suitable for anyone from beginners to intermediate developers exploring animation, CSS art, and programming languages."
        }
      },
      {
        "@type": "Question",
        "name": "How is my privacy handled when I use the site?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "CodeHemu collects minimal personal information when you contact us (for example name and email). The site also collects automated analytics data (IP, device/browser, pages visited, time on site) to improve performance and content."
        }
      },
      {
        "@type": "Question",
        "name": "Can I request deletion or update of my personal data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. You can contact hello@codehemu.in to request access, correction, or deletion of your personal data."
        }
      },
      {
        "@type": "Question",
        "name": "Do you use cookies and how can I control them?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. cookies and similar technologies are used for analytics and advertising. Manage cookies through your browser"
        }
      }
    ],

  "@type":"WebPage",
  "publisher": {
    "@id": "#organization"
  },

  "@id":"#webpage",
  "url":"",
  "name":"",

  "description":"",

  "description":"",

  "isPartOf":{
    "@id":"#website"
  },
  "about":{
    "@id":"#organization"
  },
  "inLanguage":"en",
  "breadcrumb":{
    "@id":"#breadcrumb"
  }
}

